// xdg_popup

// xdg_popup_desc is the wire description of xdg_popup.
pub const xdg_popup_desc = wayland.IfaceDesc{
	name:     'xdg_popup'
	version:  7
	requests: [
		wayland.MsgDesc{
			name:       'destroy'
			opcode:     0
			destructor: true
		},
		wayland.MsgDesc{
			name:   'grab'
			opcode: 1
			args:   [
				wayland.ArgDesc{
					name:  'seat'
					kind:  .obj
					iface: 'wl_seat'
				},
				wayland.ArgDesc{
					name: 'serial'
					kind: .uint
				},
			]
		},
		wayland.MsgDesc{
			name:   'reposition'
			opcode: 2
			since:  3
			args:   [
				wayland.ArgDesc{
					name:  'positioner'
					kind:  .obj
					iface: 'xdg_positioner'
				},
				wayland.ArgDesc{
					name: 'token'
					kind: .uint
				},
			]
		},
	]
	events:   [
		wayland.MsgDesc{
			name:   'configure'
			opcode: 0
			args:   [
				wayland.ArgDesc{
					name: 'x'
					kind: .int
				},
				wayland.ArgDesc{
					name: 'y'
					kind: .int
				},
				wayland.ArgDesc{
					name: 'width'
					kind: .int
				},
				wayland.ArgDesc{
					name: 'height'
					kind: .int
				},
			]
		},
		wayland.MsgDesc{
			name:   'popup_done'
			opcode: 1
		},
		wayland.MsgDesc{
			name:   'repositioned'
			opcode: 2
			since:  3
			args:   [
				wayland.ArgDesc{
					name: 'token'
					kind: .uint
				},
			]
		},
	]
}

// XdgPopup is a client side proxy for xdg_popup.
// A popup surface is a short-lived, temporary surface. It can be used to
// implement for example menus, popovers, tooltips and other similar user
// interface concepts. A popup can be made to take an explicit grab. See
// xdg_popup.grab for details. When the popup is dismissed, a popup_done
// event will be sent out, and at the same time the surface will be unmapped.
// See the xdg_popup.popup_done event for details. Explicitly destroying the
// xdg_popup object will also dismiss the popup and unmap the surface.
// Clients that want to dismiss the popup when another surface of their own
// is clicked should dismiss the popup using the destroy request. A newly
// created xdg_popup will be stacked on top of all previously created
// xdg_popup surfaces associated with the same xdg_toplevel. The parent of an
// xdg_popup must be mapped (see the xdg_surface description) before the
// xdg_popup itself. The client must call wl_surface.commit on the
// corresponding wl_surface for the xdg_popup state to take effect.
pub struct XdgPopup {
	wayland.Object
}

// xdg_popup_proxy wraps an object id in a XdgPopup proxy.
pub fn xdg_popup_proxy(conn &wayland.Connection, id u32) XdgPopup {
	return XdgPopup{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'xdg_popup'
		}
	}
}

// XdgPopupListener receives the events of a xdg_popup object.
pub interface XdgPopupListener {
	// This event asks the popup surface to configure itself given the
	// configuration. The configured state should not be applied immediately. See
	// xdg_surface.configure for details. The x and y arguments represent the
	// position the popup was placed at given the xdg_positioner rule, relative
	// to the upper left corner of the window geometry of the parent surface. For
	// version 2 or older, the configure event for an xdg_popup is only ever sent
	// once for the initial configuration. Starting with version 3, it may be
	// sent again if the popup is setup with an xdg_positioner with set_reactive
	// requested, or in response to xdg_popup.reposition requests.
mut:
	configure(proxy XdgPopup, x i32, y i32, width i32, height i32)
	// The popup_done event is sent out when a popup is dismissed by the
	// compositor. The client should destroy the xdg_popup object at this point.
	popup_done(proxy XdgPopup)
	// The repositioned event is sent as part of a popup configuration sequence,
	// together with xdg_popup.configure and lastly xdg_surface.configure to
	// notify the completion of a reposition request. The repositioned event is
	// to notify about the completion of a xdg_popup.reposition request. The
	// token argument is the token passed in the xdg_popup.reposition request.
	// Immediately after this event is emitted, xdg_popup.configure and
	// xdg_surface.configure will be sent with the updated size and position, as
	// well as a new configure serial. The client should optionally update the
	// content of the popup, but must acknowledge the new popup configuration for
	// the new position to take effect. See xdg_surface.ack_configure for
	// details.
	repositioned(proxy XdgPopup, token u32)
}

// NoopXdgPopupListener ignores every xdg_popup event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopXdgPopupListener {}

pub fn (mut listener NoopXdgPopupListener) configure(_proxy XdgPopup, _x i32, _y i32, _width i32, _height i32) {
}

pub fn (mut listener NoopXdgPopupListener) popup_done(_proxy XdgPopup) {
}

pub fn (mut listener NoopXdgPopupListener) repositioned(_proxy XdgPopup, _token u32) {
}

struct XdgPopupSink {
mut:
	proxy    XdgPopup
	listener XdgPopupListener = NoopXdgPopupListener{}
}

fn (mut s XdgPopupSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			x := msg.arg_int(0)!
			y := msg.arg_int(1)!
			width := msg.arg_int(2)!
			height := msg.arg_int(3)!
			s.listener.configure(s.proxy, x, y, width, height)
		}
		1 {
			s.listener.popup_done(s.proxy)
		}
		2 {
			token := msg.arg_u32(0)!
			s.listener.repositioned(s.proxy, token)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives xdg_popup events.
pub fn (proxy &XdgPopup) set_listener(listener XdgPopupListener) ! {
	proxy.conn.set_sink(proxy.id, XdgPopupSink{
		proxy:    *proxy
		listener: listener
	})!
}

// This destroys the popup. Explicitly destroying the xdg_popup object will
// also dismiss the popup, and unmap the surface. If this xdg_popup is not
// the "topmost" popup, the xdg_wm_base.not_the_topmost_popup protocol error
// will be sent.
pub fn (proxy &XdgPopup) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// This request makes the created popup take an explicit grab. An explicit
// grab will be dismissed when the user dismisses the popup, or when the
// client destroys the xdg_popup. This can be done by the user clicking
// outside the surface, using the keyboard, or even locking the screen
// through closing the lid or a timeout. If the compositor denies the grab,
// the popup will be immediately dismissed. This request must be used in
// response to some sort of user action like a button press, key press, or
// touch down event. The serial number of the event should be passed as
// 'serial'. The parent of a grabbing popup must either be an xdg_toplevel
// surface or another xdg_popup with an explicit grab. If the parent is
// another xdg_popup it means that the popups are nested, with this popup now
// being the topmost popup. Nested popups must be destroyed in the reverse
// order they were created in, e.g. the only popup you are allowed to destroy
// at all times is the topmost one. When compositors choose to dismiss a
// popup, they may dismiss every nested grabbing popup as well. When a
// compositor dismisses popups, it will follow the same dismissing order as
// required from the client. If the topmost grabbing popup is destroyed, the
// grab will be returned to the parent of the popup, if that parent
// previously had an explicit grab. If the parent is a grabbing popup which
// has already been dismissed, this popup will be immediately dismissed. If
// the parent is a popup that did not take an explicit grab, an error will be
// raised. During a popup grab, the client owning the grab will receive
// pointer and touch events for all their surfaces as normal (similar to an
// "owner-events" grab in X11 parlance), while the top most grabbing popup
// will always have keyboard focus.
pub fn (proxy &XdgPopup) grab(seat wl.WlSeat, serial u32) ! {
	proxy.conn.request(proxy.id, 1, [
		wayland.ArgValue(wayland.ObjectRef{ id: seat.id }),
		wayland.ArgValue(serial),
	])!
}

// Reposition an already-mapped popup. The popup will be placed given the
// details in the passed xdg_positioner object, and a xdg_popup.repositioned
// followed by xdg_popup.configure and xdg_surface.configure will be emitted
// in response. Any parameters set by the previous positioner will be
// discarded. The passed token will be sent in the corresponding
// xdg_popup.repositioned event. The new popup position will not take effect
// until the corresponding configure event is acknowledged by the client. See
// xdg_popup.repositioned for details. The token itself is opaque, and has no
// other special meaning. If multiple reposition requests are sent, the
// compositor may skip all but the last one. If the popup is repositioned in
// response to a configure event for its parent, the client should send an
// xdg_positioner.set_parent_configure and possibly an
// xdg_positioner.set_parent_size request to allow the compositor to properly
// constrain the popup. If the popup is repositioned together with a parent
// that is being resized, but not in response to a configure event, the
// client should send an xdg_positioner.set_parent_size request.
pub fn (proxy &XdgPopup) reposition(positioner XdgPositioner, token u32) ! {
	proxy.conn.request(proxy.id, 2, [
		wayland.ArgValue(wayland.ObjectRef{ id: positioner.id }),
		wayland.ArgValue(token),
	])!
}

// xdg_popup.error: values of the xdg_popup protocol enum.
// tried to grab after being mapped
pub const xdg_popup_error_invalid_grab = u32(0)

// bind_xdg_wm_base binds the xdg_wm_base global to a typed proxy.
pub fn bind_xdg_wm_base(conn &wayland.Connection, global wayland.Global) !XdgWmBase {
	version := if global.version < xdg_wm_base_desc.version {
		global.version
	} else {
		xdg_wm_base_desc.version
	}
	object := conn.bind_global(global, 'xdg_wm_base', version, &xdg_wm_base_desc)!
	return XdgWmBase{
		Object: object
	}
}
